export type ExerciseDetail={start:string;execution:string[];rules:string[];equipment:string[];figure?:number;source:string;sourceUrl?:string;};
const common='Приложение № 5 к Наставлению по физической подготовке; редакция приказа № 230 от 08.12.2025.';
export const verifiedExerciseDetails:Record<number,ExerciseDetail>={
1:{start:'Упор лёжа: руки и корпус прямые, ноги вместе.',execution:['Согнуть руки до касания грудью пола либо технического приспособления высотой не более 5 см.','Разогнуть руки и вернуться в упор лёжа.'],rules:['Положение упора лёжа фиксируется не менее 1 секунды; продолжать движение после объявления счёта.','Не допускаются разведение ног, сгибание тела и ног, отдых в упоре на согнутых руках.','Выполняется в спортивной форме одежды. При нарушении условий повторение не засчитывается.'],equipment:['Ровная поверхность пола','Допускается техническое приспособление высотой не более 5 см'],figure:1,source:common},
2:{start:'Лёжа на спине, ноги согнуты, ступни прижаты к полу; руки за головой, пальцы сцеплены; лопатки касаются пола.',execution:['Наклонить туловище вперёд до касания локтями коленей.','Вернуться в исходное положение лёжа на спине.','Выполнять в течение одной минуты.'],rules:['Ступни не должны отрываться от пола.','Допускается фиксация голеностопов партнёром.','Продолжать движение после объявления счёта; при нарушении условий повторение не засчитывается.'],equipment:['Гимнастический мат или ровная поверхность','При необходимости партнёр для фиксации голеностопов'],figure:2,source:common},
3:{start:'Вис на перекладине хватом сверху; руки и тело прямые, ноги вместе, тело неподвижно.',execution:['Согнуть руки и подтянуться так, чтобы подбородок оказался выше грифа перекладины.','Разогнуть руки и опуститься в вис.'],rules:['Положение виса фиксируется не менее 1 секунды.','Разрешается разводить ноги до ширины плеч и незначительно сгибать тазобедренные и коленные суставы.','Выполнение рывком и махом не допускается.'],equipment:['Перекладина'],figure:3,source:common},
4:{start:'Вис на перекладине хватом сверху; руки и тело прямые, ноги вместе, тело неподвижно.',execution:['Поднять ноги до касания грифа перекладины.','Опустить ноги и самостоятельно принять неподвижное положение виса.'],rules:['Положение виса фиксируется не менее 1 секунды.','Разрешается разводить ноги до ширины плеч и незначительно сгибать колени.','Выполнение махом не допускается.'],equipment:['Перекладина'],figure:4,source:common},
5:{start:'Вис на перекладине хватом сверху; руки и тело прямые, ноги вместе, тело неподвижно.',execution:['Сгибая руки и поднимая ноги к перекладине, выполнить переворот вокруг грифа.','Принять упор на прямые руки.','Опуститься в вис произвольным способом.'],rules:['Положение упора и положение виса фиксируются не менее 1 секунды.','Допускается разведение ног до ширины плеч и незначительное сгибание коленей.','Не допускаются мах, касание подбородком перекладины, отдых в упоре и положение лёжа на животе с согнутым корпусом на грифе.'],equipment:['Перекладина'],figure:5,source:common},
6:{start:'Вис на перекладине хватом сверху; руки и тело прямые, ноги вместе, тело неподвижно.',execution:['Поставить в упор сначала одну согнутую руку, затем вторую либо обе руки одновременно.','Разогнуть руки и принять упор на прямых руках.','Опуститься в вис произвольным способом.'],rules:['Положение упора и положение виса фиксируются не менее 1 секунды.','Не допускаются мах, отдых в упоре и положение лёжа на животе, согнувшись на грифе.','В тексте редакции после изменения приказом № 146 отдельный абзац признан утратившим силу.'],equipment:['Перекладина'],figure:6,source:common},
7:{start:'Вис на перекладине хватом сверху; руки и тело прямые, ноги вместе.',execution:['Комплекс состоит из подтягивания, поднимания ног, подъёма переворотом и подъёма силой на перекладине.','Каждый элемент выполняется по описанию соответствующего отдельного упражнения.','В первом комплексе элементы можно начать в любой последовательности.'],rules:['Во втором и последующих комплексах сохраняется выбранная очередность элементов.','Оценка определяется общим количеством выполненных комплексов.','Нарушение условий выполнения элемента означает, что повторение не засчитывается.'],equipment:['Перекладина'],figure:7,source:common},
8:{start:'Упор на брусьях: руки и тело прямые, ноги вместе, тело неподвижно.',execution:['Согнуть руки и опуститься в упор на согнутых руках так, чтобы плечевой сустав оказался ниже локтевого.','Разогнуть руки и вернуться в упор на брусьях.'],rules:['Положение упора на прямых руках фиксируется не менее 1 секунды.','Разрешается незначительно сгибать ноги и корпус, отдыхать в упоре на прямых руках.','Не допускаются мах и отдых в упоре на согнутых руках.'],equipment:['Гимнастические брусья'],figure:8,source:common},
9:{start:'Упор на брусьях: руки и тело прямые, ноги вместе, тело неподвижно.',execution:['Поднять прямые ноги и удерживать их над жердями.','Время отсчитывается с момента фиксации положения «угол» до опускания пяток ниже жердей.'],rules:['Разрешается незначительно сгибать и разводить ноги.','Сгибать руки при фиксации положения «угол» нельзя.','При нарушении условий время останавливается.'],equipment:['Гимнастические брусья'],figure:9,source:common},
10:{start:'Стойка ноги врозь; хват сверху одной рукой за дужку гири.',execution:['Поднять гирю вверх и зафиксировать на прямой руке не менее 1 секунды.','Опустить гирю и после замаха назад повторить подъём.','Выполнять одной рукой либо поочерёдно двумя руками; смена рук один раз на замахе вперёд.'],rules:['Результат — число подъёмов одной рукой либо сумма подъёмов обеими руками.','Допускается отдых с гирей на прямой руке вверху; разрешены тяжелоатлетический пояс и бинты/напульсники.','Не допускаются дожимание, отдых с гирей внизу, касание свободной рукой тела, более одного замаха и касание гирей пола.','Гиря: женщины — 16 кг, мужчины — 24 кг. Весовые категории: женщины 60/70/70+ кг; мужчины 70/80/80+ кг.'],equipment:['Гиря установленной массы'],figure:10,source:common},
11:{start:'Стойка ноги врозь; гири находятся на груди, лежат на предплечьях, руки прижаты к туловищу.',execution:['Вытолкнуть обе гири вверх и зафиксировать на прямых руках не менее 1 секунды.','Опустить гири обратно на грудь.'],rules:['Допускается отдых с гирями на груди и в положении фиксации на прямых руках после толчка.','Разрешены тяжелоатлетический пояс и бинты/напульсники. Ставить гири на плечи нельзя.','Гиря: женщины — 16 кг, мужчины — 24 кг. Весовые категории: женщины 60/70/70+ кг; мужчины 70/80/80+ кг.'],equipment:['Две гири установленной массы'],figure:11,source:common}

,12:{start:'Стойка ноги врозь; гири находятся на груди, лежат на предплечьях, руки прижаты к туловищу.',execution:['Вытолкнуть гири вверх и зафиксировать на прямых руках не менее 1 секунды.','Опустить гири на грудь, затем без остановки опустить вниз и снова поднять на грудь.'],rules:['Допускается отдых на груди после подъёма из нижнего положения и с гирями на прямых руках после толчка.','Не допускаются постановка гирь на плечи, отдых при опускании после толчка, отдых с гирями внизу, более одного замаха и касание гирями пола.','Гиря: женщины — 16 кг, мужчины — 24 кг. Весовые категории: женщины 60/70/70+ кг; мужчины 70/80/80+ кг.'],equipment:['Две гири установленной массы'],figure:12,source:common},
13:{start:'Комплекс включает приседание с гирей 24 кг, подтягивание на перекладине, поднимание ног к перекладине и сгибание-разгибание рук в упоре лёжа.',execution:['Выполнить четыре входящих упражнения по правилам соответствующих отдельных упражнений.','Каждое упражнение выполняется по четыре раза.','Норматив определяется временем выполнения четырёх комплексов.'],rules:['При приседании тазобедренный сустав должен быть ниже коленного; гиря удерживается на груди произвольным хватом.','При нарушении условий повторение не засчитывается; разрешено повторное выполнение упражнения комплекса.'],equipment:['Гиря 24 кг','Перекладина','Ровная поверхность пола'],figure:13,source:common},
14:{start:'Лёжа на спине на горизонтальной скамье; штанга на прямых руках, затылок и ягодицы прижаты к скамье, ступни на помосте; хват сверху.',execution:['Согнуть руки до касания грифом груди.','Разогнуть руки и выполнить жим.','Зафиксировать штангу на прямых руках не менее 1 секунды.'],rules:['Обязательны горизонтальная скамья со специально оборудованными стойками и страховка.','Разрешены отдых со штангой на прямых руках, помощь при снятии/постановке штанги, тяжелоатлетический пояс и бинты/напульсники.','Не допускаются выполнение без страховки, другие виды хвата, изменение исходного положения, отрыв ступней или затылка, дополнительная экипировка.','Вес штанги: женщины — 30 кг, мужчины — 70 кг. Весовые категории: женщины 60/70/70+ кг; мужчины 70/80/80+ кг.'],equipment:['Горизонтальная скамья со стойками','Штанга установленной массы','Страховка'],figure:14,source:common},
15:{start:'Стойка ноги врозь; обеими руками произвольным хватом удерживать гриф штанги.',execution:['Поднять штангу до полного выпрямления ног и спины.','Зафиксировать положение не менее 1 секунды.','Опустить штангу до касания дисками пола, не выпуская гриф, и повторить подъём.'],rules:['Разрешается отдыхать с выпрямленными ногами и спиной; допускается тяжелоатлетический пояс.','Не допускаются шаги вперёд/назад, помощь бёдрами, двойное движение при подъёме, бросание штанги и дополнительная экипировка.','Вес штанги: женщины — 50 кг, мужчины — 80 кг. Весовые категории: женщины 60/70/70+ кг; мужчины 70/80/80+ кг.'],equipment:['Штанга установленной массы','Диски и ровная площадка'],figure:15,source:common},
16:{start:'Стойка ноги врозь; штанга горизонтально на плечах, корпус прямой, ноги выпрямлены и разведены, хват двумя руками за гриф.',execution:['Согнуть ноги и опустить туловище до положения, когда верхняя поверхность бедра у тазобедренного сустава окажется ниже уровня коленного сустава.','Встать до полного выпрямления ног и туловища.'],rules:['Разрешается отдыхать со штангой стоя на прямых ногах; допускается тяжелоатлетический пояс.','Не допускаются шаги вперёд/назад и дополнительная экипировка.','Вес штанги: женщины — 30 кг, мужчины — 70 кг. Весовые категории: женщины 60/70/70+ кг; мужчины 70/80/80+ кг.'],equipment:['Штанга установленной массы'],figure:16,source:common},

17:{start:'Высокий старт за стартовой линией: одна нога впереди, не наступая на линию, другая отставлена назад.',execution:['По команде «НА СТАРТ» подойти к стартовой линии и принять исходное положение.','По команде «ВНИМАНИЕ» принять неподвижное положение старта.','По команде «МАРШ!» начать бег и преодолеть 60 м.'],rules:['Выполняется в спортивной форме одежды по беговой дорожке стадиона или ровной площадке с любым пригодным покрытием.','Запрещены пересечение соседней дорожки, создание помех другому военнослужащему и начало бега до команды «МАРШ!» (фальстарт).','При нарушении условий предоставляется вторая попытка; при повторном нарушении упражнение считается невыполненным.'],equipment:['Беговая дорожка стадиона или ровная площадка с пригодным покрытием'],figure:17,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
18:{start:'Высокий старт за стартовой линией: одна нога впереди, не наступая на линию, другая отставлена назад.',execution:['По команде «НА СТАРТ» подойти к стартовой линии и принять исходное положение.','По команде «ВНИМАНИЕ» принять неподвижное положение старта.','По команде «МАРШ!» начать бег и преодолеть 100 м.'],rules:['Выполняется в спортивной форме одежды по беговой дорожке стадиона или ровной площадке с любым пригодным покрытием.','Запрещены пересечение соседней дорожки, создание помех другому военнослужащему и начало бега до команды «МАРШ!» (фальстарт).','При нарушении условий предоставляется вторая попытка; при повторном нарушении упражнение считается невыполненным.'],equipment:['Беговая дорожка стадиона или ровная площадка с пригодным покрытием'],figure:17,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
19:{start:'Стартовое положение: одна нога впереди стартовой линии, другая отставлена назад; по команде «ВНИМАНИЕ» принять неподвижное положение.',execution:['По команде «МАРШ» пробежать 10 м до линии поворота.','Заступить за линию поворота ногой, развернуться и пробежать девять последующих отрезков по 10 м.','Финишировать после завершения десяти отрезков.'],rules:['Выполняется в спортивной форме одежды на ровной площадке с размеченными линиями старта и поворота.','Ширина линии старта и поворота входит в отрезок 10 м.','Не допускаются пересечение соседней дорожки, создание помех другому военнослужащему, фальстарт и использование предметов или неровностей как опоры.','При нарушении условий предоставляется вторая попытка; при повторном нарушении норматив считается невыполненным.'],equipment:['Ровная площадка','Разметка линий старта и поворота'],figure:18,source:common,sourceUrl:'https://www.consultant.ru/document/cons_doc_LAW_450143/429f0ec0902cc8cc40226528c5d52d0e3e4f244d/'}
,27:{start:'Общий или раздельный старт на заранее подготовленной лыжной трассе вне дорог.',execution:['По команде «МАРШ» начать движение по размеченной трассе.','Преодолеть дистанцию 5 км любым способом передвижения на лыжах.','Финишировать после полного прохождения дистанции.'],rules:['Выполняется на местности вне дорог по заранее подготовленной трассе.','Старт и финиш, как правило, оборудуются в одном месте.','Передвижение без лыж или с лыжами в руках не допускается.'],equipment:['Лыжи и лыжные палки','Заранее подготовленная лыжная трасса','Размеченные старт и финиш'],figure:23,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
28:{start:'На стартовой тумбе, рядом с ней либо в воде у бортика плавательного бассейна или оборудованной водной станции.',execution:['По команде «ЗАНЯТЬ МЕСТА» занять исходное положение.','По команде «НА СТАРТ» принять неподвижное положение.','По звуковому сигналу или команде «МАРШ» начать плавание и преодолеть 500 м любым способом.','На поворотах и финише обязательно касаться поворотного щита любой частью тела.'],rules:['Выполняется в спортивной форме одежды в плавательном бассейне или на оборудованной водной станции.','Разрешается любой способ плавания.','Не допускаются старт раньше команды «МАРШ», касание дна бассейна и захват за разграничительные дорожки.'],equipment:['Плавательный бассейн или оборудованная водная станция','Стартовая тумба или бортик','Поворотный щит и разграничительные дорожки'],source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'}
,29:{start:'Стоя перед устойчивой платформой (тумбой) высотой 30 см.',execution:['По команде «МАРШ» поставить одну ногу на платформу.','Выпрямляя опорную ногу, подняться на платформу и приставить вторую ногу; ноги и туловище выпрямить.','После фиксации положения опустить одну ногу на пол, приставить вторую и продолжить упражнение.','Счёт производится после возвращения в исходное положение. Выполнять в течение 10 минут.'],rules:['Используется устойчивая платформа высотой 30 см: гимнастическая скамейка, брус или ящик.','При нарушении условий повторение не засчитывается.','При остановке более 5 секунд подаётся команда «СТОП», упражнение считается невыполненным.'],equipment:['Устойчивая платформа высотой 30 см','Гимнастическая скамейка, брус или ящик'],figure:24,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'}
,30:{start:'Высокий старт перед размеченной дистанцией 10 м; гимнастические маты размещены в зоне кувырков.',execution:['По команде «ВПЕРЕД» пробежать 10 м.','Выполнить два кувырка вперед.','Прыжком повернуться кругом в обратное направление.','Выполнить еще два кувырка вперед.','Пробежать заключительные 10 м до финиша.'],rules:['Упражнение включает бег на 10 м, два кувырка вперед, прыжком поворот кругом, еще два кувырка вперед и бег на 10 м.','Исходное положение — высокий старт.','Разрешается использовать гимнастические маты при выполнении кувырков.','Выполняется в спортивной форме одежды по команде «ВПЕРЕД».'],equipment:['Ровная площадка с размеченной дистанцией','Гимнастические маты (разрешены)'],figure:25,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/obshchie-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-razvitie_3/uprazhnenie-n-30/'},
31:{start:'Стоя, скакалка находится за спиной; вращение скакалки вперед.',execution:['По команде «ВПЕРЕД» выполнять прыжки на двух ногах с одновременным вращением скакалки вперед.','Продолжать прыжки в течение одной минуты.','Результат определяется количеством выполненных прыжков.'],rules:['Прыжки выполняются на двух ногах в течение одной минуты.','Разрешается использовать скакалку со счетчиком оборотов.','Более одного оборота скакалки во время одного прыжка не допускается.','При остановке разрешается продолжить упражнение; время не останавливается, счет продолжается.','Выполняется в спортивной форме одежды по команде «ВПЕРЕД».'],equipment:['Скакалка (допускается модель со счетчиком оборотов)','Секундомер'],figure:26,source:common,sourceUrl:'https://www.consultant.ru/document/cons_doc_LAW_450143/9847c3d347679a2e42a132962693d54c228fa4d6/'}
,32:{start:'Стоя на бревне перед линией.',execution:['По команде «ВПЕРЕД» пройти по бревну лицом вперед.','Выполнить обратное передвижение спиной вперед.','Пройти боком в одну сторону и обратно противоположным боком.','Завершить упражнение пересечением линии с остановкой на краю бревна.'],rules:['Обязательно пересечь или наступить ногой на линии с обеих сторон бревна.','Опираться руками на бревно запрещено.','Размеры бревна: высота 110–125 см, длина 500 см, ширина 10 см. Линии шириной 10 см отмечаются в 50 см от каждого края.','При нарушении условий выполнение не засчитывается. При падении предоставляется вторая попытка.','Выполняется в спортивной форме одежды по команде «ВПЕРЕД».'],equipment:['Бревно высотой 110–125 см, длиной 500 см и шириной 10 см','Разметка линий с обеих сторон'],figure:27,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/obshchie-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-razvitie_3/uprazhnenie-n-32/'},
33:{start:'Упор на руках на брусьях.',execution:['Вариант 1: размахивание, подъем махом вперед в сед ноги врозь, перемах ног внутрь и мах назад, соскок махом вперед вправо с поворотом налево, держась за жердь двумя руками.','Вариант 2: размахивание, подъем махом вперед, мах назад, соскок махом вперед вправо с поворотом налево, держась за жердь двумя руками.','Вариант 3: размахивание, подъем махом вперед, мах назад, сед ноги врозь, перехват рук вперед, силой стойка на плечах с удержанием 2 секунды, кувырок вперед в сед ноги врозь, перемах ног внутрь и мах назад, соскок махом вперед вправо с поворотом налево.'],rules:['Предназначено для курсантов образовательных организаций.','Добавление или пропуск элементов, нарушение техники не допускаются.','Оценка: вариант 3 — 100 баллов, вариант 2 — 70 баллов, вариант 1 — 40 баллов.','Выполняется в спортивной форме одежды по команде «К СНАРЯДУ».'],equipment:['Гимнастические брусья'],figure:28,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/obshchie-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-razvitie_3/uprazhnenie-n-33/'},
34:{start:'Вис на перекладине.',execution:['Вариант 1: подъем переворотом, мах дугой, соскок махом назад.','Вариант 2: размахивание, подъем разгибом, мах дугой, соскок махом назад.','Вариант 3: размахивание, подъем разгибом, оборот назад в упоре, мах дугой, соскок махом назад.'],rules:['Предназначено для курсантов образовательных организаций.','Добавление или пропуск элементов, нарушение техники не допускаются.','Оценка: вариант 3 — 100 баллов, вариант 2 — 70 баллов, вариант 1 — 40 баллов.','Выполняется в спортивной форме одежды по команде «К СНАРЯДУ».'],equipment:['Гимнастическая перекладина'],figure:29,source:common,sourceUrl:'https://www.consultant.ru/document/cons_doc_LAW_450143/f405b97bcab655d2110066f8d6e53df1e4a4e935/'},
35:{start:'Разбег перед гимнастическим мостиком.',execution:['Вариант 1: прыжок ноги врозь через козла в длину — толчок двумя ногами от мостика, постановка рук на козла, разведение ног и приземление на ноги.','Вариант 2: прыжок согнув ноги через коня (козла) в ширину — толчок двумя ногами, постановка рук на снаряд, сгибание ног, отталкивание руками и приземление.','Вариант 3: прыжок ноги врозь через коня в длину — толчок двумя ногами, постановка рук на дальнюю половину коня, разведение ног и приземление.'],rules:['Предназначено для курсантов образовательных организаций.','Перебор руками и касание мата рукой или руками после приземления не допускаются.','Высота гимнастического коня — 120–130 см; гимнастический мостик устанавливается произвольно.','Оценка: вариант 3 — 100 баллов, вариант 2 — 70 баллов, вариант 1 — 40 баллов.','Выполняется в спортивной форме одежды по команде «ВПЕРЕД».'],equipment:['Гимнастический конь высотой 120–130 см','Гимнастический мостик','Мат для приземления'],figure:30,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/obshchie-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-razvitie_3/uprazhnenie-n-35/'}
,36:{start:'На средней линии баскетбольной площадки в центре; мяч находится в руках по команде «ВНИМАНИЕ».',execution:['По команде «НА СТАРТ» выйти на среднюю линию в центре площадки.','По команде «ВНИМАНИЕ» взять баскетбольный мяч.','По сигналу или команде «МАРШ» вести мяч к щиту до линии штрафного броска.','Выполнить бросок двумя руками от груди в щит, поймать отскочивший мяч и бросить по кольцу без ведения.','После попадания поймать мяч, вести его к противоположному щиту, обвести пять стоек с интервалом 2 м и бросить по кольцу.','Упражнение заканчивается после попадания мяча в кольцо.'],rules:['Предназначено для курсантов образовательных организаций.','Площадка: 15 × 28 м. Используется баскетбольный мяч.','Пропуск или невыполнение элемента, а также нарушение правила ведения мяча означает, что упражнение не выполнено.'],equipment:['Баскетбольная площадка 15 × 28 м','Баскетбольный мяч','Баскетбольные щиты и кольца','Пять стоек с интервалом 2 м'],figure:33,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/obshchie-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-razvitie_3/uprazhnenie-n-36/'},
37:{start:'На пересечении боковой и средней линий мини-футбольной площадки.',execution:['По команде «НА СТАРТ» занять исходное положение.','По команде «ВНИМАНИЕ» принять неподвижное положение.','По сигналу или команде «МАРШ» пробежать к 6-метровой отметке, где установлен мяч.','Начать ведение мяча ногами любым способом, обвести пять стоек на расстоянии 1,5 м друг от друга.','После пересечения средней линии произвести удар по воротам с любого расстояния.','Упражнение заканчивается после попадания мяча в створ ворот.'],rules:['Предназначено для курсантов образовательных организаций.','Площадка: 20 × 40 м. Первая стойка находится на 10-метровой отметке от ближайших ворот.','Если пропущено или неправильно выполнено какое-либо действие, упражнение считается невыполненным.'],equipment:['Мини-футбольная площадка 20 × 40 м','Мини-футбольный мяч','Пять стоек с интервалом 1,5 м','Ворота'],figure:34,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/obshchie-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-razvitie_3/uprazhnenie-n-37/'}
,38:{start:'За линией подачи, волейбольный мяч находится в руках.',execution:['По команде «НА СТАРТ» занять исходное положение за линией подачи с мячом в руках.','По сигналу или команде «МАРШ» выполнить верхнюю прямую подачу на противоположную сторону площадки.','Добежать до зоны № 2, взять мяч на пересечении средней и боковой линий и в прыжке двумя руками перебросить его на противоположную сторону не дальше линии атаки.','Переместиться вдоль сетки приставными шагами в зону № 3 и выполнить второй бросок мяча в прыжке двумя руками.','Продолжить движение приставными шагами до зоны № 4, взять мяч на пересечении средней и боковой линий и выполнить третий бросок.','Повернуться кругом, добежать до мяча на середине линии атаки, взять его и выполнить нападающий удар с собственного набрасывания над сеткой на противоположную сторону.','Упражнение заканчивается после касания мячом площадки.'],rules:['Предназначено для курсантов образовательных организаций.','Выполняется в спортивной форме одежды на волейбольной площадке 9 × 18 м.','Высота сетки: мужчины — 2,43 м; женщины — 2,24 м.','Если пропущено или не выполнено какое-либо действие, упражнение считается невыполненным.'],equipment:['Волейбольная площадка 9 × 18 м','Волейбольная сетка высотой 2,43 м для мужчин и 2,24 м для женщин','Волейбольные мячи'],figure:35,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/obshchie-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-razvitie_3/uprazhnenie-n-38/'}
,39:{start:'На стартовой линии; оружие, элементы экипировки и ящик для боеприпасов находятся при военнослужащем.',execution:['Надеть военную форму одежды, бронежилет и защитный шлем.','Взять автомат или массогабаритный макет с пристегнутым магазином и ящик для боеприпасов массой 30 кг.','По команде «НА СТАРТ» занять положение у стартовой линии, не наступая на нее.','По команде «ВНИМАНИЕ» принять неподвижное положение.','По команде «МАРШ!» преодолеть 60 м.'],rules:['Положение автомата и груза произвольное.','Дистанция должна быть ровной.','Финиш без оружия, груза или любого элемента экипировки означает невыполнение упражнения.'],equipment:['Военная форма одежды','Бронежилет и защитный шлем','Автомат или массогабаритный макет с пристегнутым магазином','Ящик для боеприпасов массой 30 кг'],figure:36,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie/uprazhnenie-n-39/'},
40:{start:'Лежа на животе за стартовой линией, в военной форме одежды, бронежилете, защитном шлеме и с автоматом.',execution:['По команде «НА СТАРТ» принять положение для стрельбы лежа, не пересекая стартовую линию любой частью тела.','По команде «МАРШ!» встать и преодолеть 60 м с автоматом в руке.','Финишировать, сохраняя оружие и элементы экипировки при себе.'],rules:['Используются военная форма одежды, бронежилет, защитный шлем, автомат или массогабаритный макет с пристегнутым магазином.','Финиш без оружия или элементов экипировки означает невыполнение упражнения.'],equipment:['Военная форма одежды','Бронежилет и защитный шлем','Автомат или массогабаритный макет с пристегнутым магазином','Ровная дистанция 60 м'],figure:37,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie/uprazhnenie-n-40/'},
41:{start:'Высокий старт перед стартовой линией; автомат и экипировка при военнослужащем.',execution:['По команде «НА СТАРТ» подойти к стартовой линии, поставить одну ногу вперед, не наступая на линию, другую отставить назад.','По команде «ВНИМАНИЕ» принять неподвижное положение старта.','По команде «МАРШ» пробежать 100 м, заступить ногой за линию поворота, развернуться и пробежать еще три отрезка по 100 м.'],rules:['Выполняется в военной форме одежды с автоматом (или массогабаритным макетом), пристегнутым магазином, сумкой для магазинов с одним магазином и противогазом.','Ширина линии старта и поворота входит в отрезок 100 м.','Не допускаются пересечение соседней дорожки, помехи другому военнослужащему, фальстарт и использование посторонних предметов или неровностей как опоры при старте и развороте.'],equipment:['Военная форма одежды','Автомат или массогабаритный макет с пристегнутым магазином','Сумка для магазинов с одним магазином','Противогаз','Ровная площадка с линиями старта и поворота'],figure:38,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie/uprazhnenie-n-41/'},
42:{start:'Общий старт за стартовой линией; автомат и экипировка находятся при военнослужащем.',execution:['По команде «НА СТАРТ» подойти к стартовой линии.','По команде «МАРШ» начать бег.','Преодолеть 800 м по беговой дорожке стадиона или ровной дороге вне стадиона.','Финишировать после полного преодоления дистанции.'],rules:['Выполняется в военной форме одежды с автоматом (или массогабаритным макетом), пристегнутым магазином, сумкой для магазинов с одним магазином и противогазом.','Старт и финиш, как правило, оборудуются в одном месте.','На стадионе старт и финиш определяются разметкой стадиона.'],equipment:['Военная форма одежды','Автомат или массогабаритный макет с пристегнутым магазином','Сумка для магазинов с одним магазином','Противогаз','Беговая дорожка или ровная дорога'],figure:39,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie/uprazhnenie-n-42/'},
43:{start:'Общий старт на местности; военнослужащий в военной форме одежды с оружием и экипировкой.',execution:['Занять место на линии общего старта.','По команде начать марш-бросок на 5 км по выбранной местности.','Поддерживать движение до полного преодоления дистанции; разрешается переходить на шаг.','Финишировать в месте, где оборудован старт.'],rules:['Выполняется в военной форме одежды с автоматом или массогабаритным макетом, пристегнутым магазином, сумкой для магазинов с одним магазином и противогазом.','Проводится на любой местности с общего старта; старт и финиш оборудуются в одном месте. Разрешается переходить на шаг.','Дополнительное крепление оружия и снаряжения, а также их передача не допускаются.'],equipment:['Военная форма одежды','Автомат или массогабаритный макет с пристегнутым магазином','Сумка для магазинов с одним магазином','Противогаз','Маршрут 5 км'],figure:41,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie/uprazhnenie-n-43/'},
44:{start:'Общий или раздельный старт на заранее подготовленной лыжной трассе; оружие и экипировка находятся при военнослужащем.',execution:['Занять место на старте размеченной и подготовленной трассы.','По команде начать марш-бросок на лыжах на 5 км.','Преодолеть всю дистанцию на лыжах и финишировать в месте старта.'],rules:['Выполняется на любой местности с общего или раздельного старта по заранее размеченной и подготовленной трассе.','Старт и финиш оборудуются в одном месте.','Используются военная форма одежды, автомат или массогабаритный макет с пристегнутым магазином, сумка для магазинов с одним магазином и противогаз.','Дополнительное крепление оружия и снаряжения, а также их передача не допускаются.'],equipment:['Военная форма одежды','Лыжи и лыжные палки','Автомат или массогабаритный макет с пристегнутым магазином','Сумка для магазинов с одним магазином','Противогаз','Подготовленная лыжная трасса 5 км'],figure:42,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie/uprazhnenie-n-44/'}
,46:{start:'Стоя у бокового борта макета БТР; автомат в руке, противогаз в сумке.',execution:['Влезть в макет БТР через боковой борт и соскочить с противоположного борта.','Пробежать 200 м, обежать флажок, соскочить в траншею и надеть противогаз.','Выскочить из траншеи, преодолеть овраг по бревну, завал, затем ров; перенести ящик массой 30 кг с заднего бруствера на передний и обратно.','Снять противогаз, убрать его в сумку, пройти лабиринт, забор, балочный мост и разрушенную лестницу.','Преодолеть стенку, колодец и ход сообщения; метнуть массогабаритный макет гранаты Ф-1 массой 600–620 г на 15 м по щиту 2 × 1 м.','При промахе продолжать метание, но не более трех гранат; за непопадание к результату прибавляется 5 секунд.','Преодолеть палисадник, фасад дома с нижним и верхним окнами, балку и площадки; перепрыгнуть траншею.'],rules:['Предназначено для курсантов, готовящих специалистов для подразделений и воинских частей Сухопутных войск (кроме перечисленных специальных категорий), а также морской пехоты.','Выполняется в военной форме одежды с автоматом и пристегнутым магазином, сумкой для магазинов с одним магазином и противогазом.','Дистанция — 400 м.','При непопадании гранатой в цель к результату прибавляется 5 секунд.'],equipment:['Макет БТР и полоса препятствий','Автомат с пристегнутым магазином','Сумка для магазинов с одним магазином и противогаз','Ящик массой 30 кг','Макет гранаты Ф-1 массой 600–620 г'],figure:44,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_1/uprazhnenie-n-46/'},
47:{start:'Стоя во рву; военная форма одежды и противогаз.',execution:['Выскочить из рва и пробежать 60 м к первой траншее.','Обежать флажок, перепрыгнуть траншею и добежать до горки с грузом.','Поднять ящик массой 30 кг на нижнюю полку, затем на среднюю и в обратном порядке опустить на землю.','Влезть в люк механика-водителя и метнуть из верхнего люка макет гранаты Ф-1 массой 600–620 г на 13 м по кругу диаметром 2 м.','При промахе продолжать метание, но не более трех гранат; за непопадание к результату прибавляется 5 секунд.','Вылезти через запасный люк, перенести ящик массой 30 кг между брустверами рва, пройти лабиринт, забор, разрушенную лестницу, стенку, траншею и колодец.','Преодолеть пролом стенки, наклонную лестницу, балочный мост, ров, пробежать 60 м, перепрыгнуть траншею, обежать флажок, перепрыгнуть траншею, пробежать 60 м и соскочить в ров.'],rules:['Предназначено для курсантов, готовящих специалистов для танковых, зенитных ракетных, ракетных, инженерных и самоходных артиллерийских частей, а также танковых подразделений мотострелковых частей.','Выполняется в военной форме одежды с противогазом.','Дистанция — 400 м.','За непопадание гранатой в цель к результату прибавляется 5 секунд.'],equipment:['Полоса препятствий и макет люка механика-водителя','Противогаз','Ящик массой 30 кг','Макет гранаты Ф-1 массой 600–620 г'],figure:45,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_1/uprazhnenie-n-47-spetsialnoe-kontrolnoe/'},
48:{start:'Стоя у линии старта с оружием в руке.',execution:['Пробежать 200 м до линии начала полосы и обежать флажок.','Проползти по-пластунски под проволокой и преодолеть завал.','Вскочить на кормовую часть макета БМД, влезть в кормовой люк и метнуть макет гранаты Ф-1 массой 600–620 г из люка наводчика-оператора по рву.','При промахе продолжать метание, но не более трех гранат; за непопадание к результату прибавляется 5 секунд.','Вылезти через люк механика-водителя, перепрыгнуть ров 2,5 м, пройти лабиринт, забор, балки и разрушенную лестницу.','Преодолеть стенку, колодец и ход сообщения, взять ящик массой 30 кг, пробежать с ним до траншеи и положить на бруствер.','Преодолеть палисадник, фасад дома с окнами, балку и площадки, затем ров по качающемуся трапу.'],rules:['Предназначено для военнослужащих Воздушно-десантных войск.','Выполняется в военной форме одежды с автоматом и пристегнутым магазином, сумкой для магазинов с одним магазином и противогазом.','Дистанция — 400 м.','За непопадание гранатой в цель к результату прибавляется 5 секунд.'],equipment:['Макет БМД и полоса препятствий','Автомат с пристегнутым магазином','Сумка для магазинов с одним магазином и противогаз','Макет гранаты Ф-1 массой 600–620 г','Ящик массой 30 кг'],figure:46,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_1/uprazhnenie-n-48/'},
49:{start:'Стоя перед линией начала полосы; военная форма одежды и противогаз.',execution:['Пробежать 120 м вдоль полосы, обежать флажок и добежать до стойки с грузом.','Снять конец с «утки», опустить на землю, поднять груз, выбирая конец, и надежно закрепить его за «утку».','Влезть по ближнему штормтрапу на выстрел, наступая на балясины, пробежать по выстрелу до дальнего шкентеля с мусингами и спуститься по нему на землю; спрыгивать запрещено.','Пролезть в горловину, пробежать по качающейся доске; при падении повторить. Подняться по вертикальному трапу, открыть крышку люка, пролезть через люк и спуститься по наклонному трапу.','Взять груз массой 30 кг, обежать последовательно четыре стойки и вернуть груз к наклонному трапу.','Подняться по наклонному трапу, пролезть через люк, закрыть крышку и спуститься по вертикальному трапу; пройти качающуюся доску и горловину.','Повторно пройти штормтрап и выстрел, спуститься по шкентелю, пробежать до линии начала полосы, обежать флажок и пробежать 120 м.'],rules:['Предназначено для военнослужащих надводных кораблей и подводных лодок, а также курсантов, готовящих специалистов для них.','Выполняется в военной форме одежды с противогазом.','Дистанция — 360 м.','По шкентелю спускаться, не спрыгивая; при падении на качающейся доске повторить ее прохождение.'],equipment:['Морская полоса препятствий: штормтрапы, выстрел, шкентели, горловина, качающаяся доска, вертикальный и наклонный трапы','Противогаз','Груз массой 30 кг','Четыре стойки'],figure:47,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie/uprazhnenie-n-49_1/'},
50:{start:'Лежа для стрельбы перед линией начала полосы; автомат и снаряжение при военнослужащем.',execution:['Пробежать до первой вышки канатного перехода, подняться по вертикальной лестнице на террасу.','Выбрать веревку с грузом массой 30 кг до упора в перила и, не бросая, опустить ее на землю.','Пройти по нижнему тросу до второй вышки, перелезть на веревку и спуститься по ней.','Взбежать по наклонной доске на тропу, пробежать по ней, наступая на каждый отрезок, и соскочить с последнего на землю.','Пролезть через ограничительный проход и пройти второй участок тропы; затем по веревочному мосту перейти на металлическую конструкцию, пройти горизонтальную лестницу и преодолеть ее обратным направлением в висе на руках.','Спрыгнуть на землю, пройти по качающемуся бревну и подняться по наклонной стенке горки до нижнего карниза; разрешается использовать веревку.','С колена метнуть макет гранаты Ф-1 массой 600–620 г в круг диаметром 3 м; при промахе продолжать метание, но не более трех гранат, за непопадание прибавляется 5 секунд.','Спуститься по вертикальной стенке с треугольными вырезами, преодолеть сухое русло реки по выступающим камням и пересечь финишную линию.'],rules:['Предназначено для военнослужащих горных подразделений.','Выполняется в военной форме одежды с автоматом или массогабаритным макетом с пристегнутым магазином и сумкой для магазинов с одним магазином.','Дистанция — 100 м.','При срыве с камня сухого русла реки вернуться на него и продолжить движение.','За непопадание гранатой в цель к результату прибавляется 5 секунд.'],equipment:['Горная полоса препятствий с канатными переходами, тропой, веревочным мостом, качающимся бревном и горкой','Автомат с пристегнутым магазином','Сумка для магазинов с одним магазином','Груз массой 30 кг','Макет гранаты Ф-1 массой 600–620 г'],figure:48,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_1/uprazhnenie-n-50/'},
51:{start:'Стоя у линии старта; военная форма одежды без оружия.',execution:['Преодолеть веревочную лестницу через верх и спуститься любым способом.','Преодолеть двойные балки через верх с касанием земли между ними и опрокинутые провода (резинки).','Проползти под сетью «мышеловка», пробежать по пенькам брода и преодолеть шпалеру через верх.','Забежать на балансировочное бревно, пробежать по нему и спрыгнуть за ограничительную линию.','Взбежать на наклонную стенку и спрыгнуть через верх; разрешается страховочный канат.','Преодолеть разновысокие балки: высокие сверху, низкие снизу; преодолеть ирландский стол через верх без использования боковой стойки.','Нырнуть в тоннель, преодолеть высокую балку сверху и низкую снизу, разрушенную лестницу, вал, стенку, яму и вертикальную лестницу.','Преодолеть штурмовую стенку, пробежать по балкам ломаного бума, пройти лабиринт, преодолеть три стенки и финишировать.'],rules:['Выполняется в военной форме одежды без оружия.','Дистанция — 500 м.','Ирландский стол преодолевается через верх; использовать боковую стойку запрещено.','В яме запрещено использовать боковые стенки для выхода.'],equipment:['Специальная полоса препятствий с веревочной лестницей, балками, сетью, бродом, шпалерой, балансировочным бревном, наклонной стенкой, ирландским столом, тоннелем, валом и лабиринтом'],figure:49,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_1/uprazhnenie-n-51/'},
52:{start:'Стоя у линии старта; военная форма одежды без оружия.',execution:['Преодолеть забор через верх произвольным способом.','Добежать до бревна, подняться по лестнице, пройти до края и спрыгнуть за ограничительную линию.','Преодолеть бочку через верх с опорой рукой и/или ногой, затем ирландский стол без использования боковых стоек.','Обогнуть шесть столбов только с одной стороны и метнуть гранату в проем переборки до попадания.','Подняться по веревочной лестнице, проползти по горизонтальному тросу, коснуться балки, спуститься по вертикальному канату и перепрыгнуть ров с помощью каната.','Прыжком преодолеть ров шириной 4 м, проползти тоннель и вылезти из бочки.','Пройти по нижнему тросу, держась за верхний, обогнуть стойки, подняться по наклонным балкам, пройти по канату, коснуться горизонтальной балки и спрыгнуть вниз.','Преодолеть яму с использованием каната, наступить на площадку и спрыгнуть; добежать до финиша.'],rules:['Выполняется в военной форме одежды без оружия.','Дистанция — 305 м.','Гранату метают в проем переборки до попадания.'],equipment:['Специальная морская полоса препятствий с забором, бревном, бочкой, ирландским столом, переборкой, веревочной лестницей, тросами, тоннелем и ямой','Гранаты'],figure:50,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_1/uprazhnenie-n-52/'}
,45:{start:'Стоя в траншее; военная форма одежды, без оружия.',execution:['По команде «ВПЕРЕД» метнуть гранату массой 600–620 г из траншеи на 20 м по стенке с проломами или в площадку 1 × 2,6 м перед стенкой. Засчитывается прямое попадание.','При промахе первой гранатой продолжать метание, но не более трех гранат до поражения цели; за промах к результату прибавляется 5 секунд.','Выскочить из траншеи, пробежать 100 м к линии начала полосы, обежать флажок и преодолеть ров шириной 2,5 м.','Пройти лабиринт, перелезть забор, подняться по вертикальной лестнице на разрушенный мост, пройти по балкам с перепрыгиванием разрывов и спрыгнуть с конца моста.','Преодолеть три ступени разрушенной лестницы с обязательным касанием земли двумя ногами между ступенями, пробежать под четвертой ступенью и пролезть в пролом стенки.','Соскочить в траншею, пройти ход сообщения, выбраться из колодца, перепрыгнуть стенку, взбежать по наклонной лестнице на четвертую ступень и сбежать по разрушенной лестнице.','Подняться на балку разрушенного моста, пройти по балкам с перепрыгиванием разрывов, сбежать по наклонной доске, преодолеть ров шириной 2 м, пробежать 20 м, обежать флажок и пробежать 100 м обратно.'],rules:['Выполняется в военной форме одежды без оружия. Дистанция — 400 м.','Исходное положение — стоя в траншее.','Граната массой 600–620 г должна попасть прямо в стенку/пролом или в площадку 1 × 2,6 м перед стенкой. При промахе каждой гранатой к результату добавляется 5 секунд; всего допускается не более трех гранат.','Обязательны прохождение всех препятствий в установленной последовательности и соблюдение критериев каждого элемента.'],equipment:['Единая полоса препятствий с траншеей, рвами, лабиринтом, забором, разрушенным мостом, лестницей, стенкой и колодцем','Гранаты массой 600–620 г','Флажки и разметка 400-метровой дистанции'],figure:43,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'}
,53:{start:'Исходное положение — изготовка к бою; проверка проводится в соответствии с установленным комплексом приемов рукопашного боя.',execution:['Комплекс включает контроль выполнения приемов и действий рукопашного боя с оружием и без оружия.','Состав комплекса, последовательность элементов и демонстрационные рисунки приведены в официальном тексте упражнения № 53.','Для подготовки и проверки использовать утвержденную программу занятия и демонстрацию квалифицированного руководителя.'],rules:['Упражнение относится к специальным физическим упражнениям по рукопашному бою.','В официальном тексте приведены приемы, ошибки выполнения и рисунки 51–85.','Данная карточка намеренно не воспроизводит пошаговые боевые действия; для проведения занятия необходимо использовать официальный текст и подготовленного руководителя.'],equipment:['Учебная площадка и защитное оснащение по программе занятия','Тренировочные макеты и средства защиты — по установленному порядку'],source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_2/uprazhnenie-n-53/'},
54:{start:'Стоя на исходной позиции перед мишенью; военная форма одежды, штатный бронежилет и защитная каска.',execution:['Выполняется проверка метания трех ножей по обозначенной зоне мишени № 8.','Учитываются только ножи, оставшиеся в мишени; если нож попал в мишень, но затем упал, бросок не засчитывается.','Результат — количество засчитанных попаданий в зону поражения.'],rules:['Используются штатные ножи «Ратник» 6×9-1 либо ножи, соответствующие ограничениям приказа: общая длина до 300 мм, клинок до 160 мм, обух до 8 мм, масса до 300 г.','Зона поражения — 20 × 30 см слева от оси мишени; дистанция — не менее 3 м.','Разрешается выбор дистанции и способа хвата, но карточка не содержит инструкций по технике метания.','Результат: 3 попадания — 100 баллов; 2 — 70; 1 — 40.'],equipment:['Мишень № 8 с обозначенной зоной поражения','Три штатных ножа, соответствующих ограничениям приказа','Военная форма одежды, штатный бронежилет и каска'],figure:86,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/proverka-i-otsenka-voennosluzhashchego-po/uprazhnenie-n-54/'},
55:{start:'Стоя на исходной позиции перед мишенью; военная форма одежды, штатный бронежилет и защитный шлем.',execution:['Выполняется проверка метания трех малых пехотных лопат по обозначенной зоне мишени № 8.','Учитываются только лопаты, оставшиеся в мишени; если лопата попала в мишень, но затем упала, бросок не засчитывается.','Результат — количество засчитанных попаданий в зону поражения.'],rules:['Используются штатные малые пехотные лопаты с фиксированным штыком.','Зона поражения — выше пояса, на расстоянии 700 мм от основания мишени; дистанция — не менее 5 м.','По приказу метание выполняется хватом за рукоятку; карточка не содержит инструкций по технике метания.','Результат: 3 попадания — 100 баллов; 2 — 70; 1 — 40.'],equipment:['Мишень № 8 с обозначенной зоной поражения','Три штатные малые пехотные лопаты с фиксированным штыком','Военная форма одежды, штатный бронежилет и защитный шлем'],figure:86,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/proverka-i-otsenka-voennosluzhashchego-po/uprazhnenie-n-55/'},
56:{start:'На стартовой тумбе, рядом с ней либо в воде у бортика бассейна; форма одежды № 2В, ботинки надеты, автомат (макет) за спиной.',execution:['По команде «ЗАНЯТЬ МЕСТА» занять положение на тумбе, рядом с ней либо в воде у бортика.','По команде «НА СТАРТ» принять неподвижное положение.','По звуковому сигналу или команде «МАРШ» преодолеть 50 м любым способом плавания.','На повороте и финише коснуться поворотного щита любой частью тела.'],rules:['Форма одежды № 2В в ботинках; автомат или массогабаритный макет располагается за спиной.','Не допускаются фальстарт, касание дна бассейна и захват за разграничительные дорожки.','Упражнение не выполнено при потере оружия или предметов обмундирования.','Мера безопасности при занятии: выполнять только при организованном наблюдении и готовности спасательного обеспечения.'],equipment:['Плавательный бассейн или оборудованная водная станция','Форма одежды № 2В и ботинки','Автомат или массогабаритный макет','Стартовая тумба или бортик, поворотный щит'],figure:87,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_3/uprazhnenie-n-56/'},
57:{start:'На стартовой тумбе, рядом с ней либо в воде у бортика; форма одежды № 2В, ботинки сняты и закреплены за поясным ремнем, автомат за спиной.',execution:['По команде «ЗАНЯТЬ МЕСТА» занять положение на тумбе, рядом с ней либо в воде у бортика.','По команде «НА СТАРТ» принять неподвижное положение.','По звуковому сигналу или команде «МАРШ» преодолеть 100 м любым способом плавания.','На повороте и финише коснуться поворотного щита любой частью тела.'],rules:['Форма одежды № 2В; ботинки сняты и заправлены за поясной ремень, автомат или массогабаритный макет с пристегнутым магазином располагается за спиной.','Не допускаются фальстарт, касание дна бассейна и захват за разграничительные дорожки.','Упражнение не выполнено при потере оружия или предметов обмундирования.','Мера безопасности при занятии: выполнять только при организованном наблюдении и готовности спасательного обеспечения.'],equipment:['Плавательный бассейн или оборудованная водная станция','Форма одежды № 2В','Автомат или массогабаритный макет с пристегнутым магазином','Стартовая тумба или бортик, поворотный щит'],figure:88,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_3/uprazhnenie-n-57/'},
58:{start:'На стартовой тумбе, бортике бассейна или в воде; форма одежды № 2В без ботинок.',execution:['Стартовать индивидуально по готовности со стартовой тумбы, бортика либо из воды.','Преодолеть под водой максимально возможное расстояние любым способом, ориентируясь по линии на дне бассейна или натянутому шнуру на глубине 1–1,5 м.','Результат фиксируется в момент появления любой части тела на поверхности воды.'],rules:['Форма одежды № 2В без ботинок.','Передвижение вперед с подтягиванием за путеводный шнур и отталкивание от дна бассейна не допускаются.','При потере сознания (засыпании) результат не засчитывается.','Мера безопасности при занятии: только под непосредственным наблюдением специалиста по плаванию, с готовым спасательным обеспечением; не выполнять в одиночку.'],equipment:['Бассейн с разметкой на дне или путеводным шнуром на глубине 1–1,5 м','Форма одежды № 2В без ботинок','Стартовая тумба или бортик','Спасательное обеспечение'],figure:89,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_3/uprazhnenie-n-58/'}
,59:{start:'Раздельный старт на размеченной дистанции 3 км; военнослужащий в установленной форме и экипировке.',execution:['Преодолеть дистанцию 3 км с выполнением контрольных этапов, предусмотренных упражнением.','Контрольные этапы стрельбы и метания выполняются на специально оборудованных рубежах по отдельным утвержденным правилам и под руководством уполномоченных специалистов.','После выполнения контрольных этапов продолжить бег и финишировать.'],rules:['Старт и финиш, как правило, оборудуются в одном месте; старт раздельный.','Используется установленный комплект формы и экипировки.','За промах в стрельбе добавляется 20 секунд; за метание менее чем на 30 м — 10 секунд.','Карточка не воспроизводит процедуры обращения с оружием и метания; для них применяется отдельная утвержденная инструкция.'],equipment:['Размеченная дистанция 3 км','Установленный комплект формы и экипировки','Оборудованные контрольные рубежи'],figure:90,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_4/uprazhnenie-n-59/'},
60:{start:'Раздельный старт на дистанции 1100 м; военная форма одежды, автомат с магазином, сумка для магазинов и противогаз.',execution:['Пробежать 1000 м.','Преодолеть ров.','Пробежать по проходам лабиринта.','Перелезть через забор.','Преодолеть разрушенную лестницу, наступая на три ступени; соскочить на землю и пробежать под четвертой ступенью.','Преодолеть стенку и перепрыгнуть траншею.','Финишировать после прохождения всей полосы препятствий.'],rules:['Дистанция — 1100 м; старт раздельный.','Выполняется с автоматом и пристегнутым магазином, сумкой для магазинов с одним магазином и противогазом.','Все препятствия преодолеваются в установленной последовательности.'],equipment:['Размеченная дистанция 1100 м','Ров, лабиринт, забор, разрушенная лестница, стенка и траншея','Автомат с пристегнутым магазином','Сумка для магазинов с одним магазином','Противогаз'],source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
61:{start:'На стартовой линии комплексной площадки; военная форма и установленное защитное снаряжение.',execution:['Выполнить комплексное упражнение «Квадрат» на размеченной площадке общей дистанцией 165 м.','Комплекс объединяет перемещения между секторами, преодоление препятствий и контрольные действия с учебным инвентарем.','Завершить маршрут в установленной последовательности.'],rules:['Используются военная форма, бронежилет, защитный шлем, наколенники, налокотники, перчатки и предусмотренный учебный комплект инвентаря.','Пропуск действия, нарушение условий или незачетное попадание учебного макета означает невыполнение упражнения.','За непопадание учебного макета в сектор к результату прибавляется 2 секунды.','Подробная схема маршрута и контрольные действия приведены в официальном рисунке и тексте упражнения.'],equipment:['Комплексная площадка «Квадрат» с разметкой','Штатное защитное снаряжение','Учебные макеты и инвентарь по схеме упражнения'],figure:91,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_4/uprazhnenie-n-61/'},
62:{start:'Внутри стационарного гимнастического колеса; руки и ноги закреплены ремнями.',execution:['Выполнить 10 оборотов в одну сторону и 10 оборотов в противоположную.','Начало и окончание упражнения фиксируются в момент прохождения вертикали головой вверх.','Направление первого вращения выбирается самостоятельно.'],rules:['Переход к вращению в другую сторону — не более 30 секунд.','Время не останавливается после первых 10 оборотов; оценивается общее время 20 оборотов.','Выполнять упражнение без крепления ремнями рук и ног к колесу запрещено.'],equipment:['Стационарное гимнастическое колесо','Фиксирующие ремни для рук и ног','Секундомер'],figure:92,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
63:{start:'Стойка внутри подвижного гимнастического колеса на прямых ногах; хват сверху за внешние края поперечных ручек.',execution:['Перенести вес тела на одну ногу и начать движение колеса в сторону.','Рывковым движением плеч и груди перейти на внутренний обод.','Перенося вес тела и активно работая руками и ногами, выполнить спираль.','Для завершения спирали рывком рук назад поднять колесо и поставить его на оба обода.','Количество выполненных спиралей суммируется.'],rules:['Разрешается выполнять упражнение в любую сторону.','Разрешается помощь при входе в спираль.','Оценка производится по сумме выполненных спиралей.'],equipment:['Подвижное гимнастическое колесо'],figure:93,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
64:{start:'Внутри лопинга; руки и ноги закреплены ремнями.',execution:['Выполнить четыре серии по пять оборотов вперед.','После каждой серии изменить направление вращения.','Начало и окончание упражнения фиксируются в момент прохождения рамой лопинга верхнего вертикального положения.'],rules:['Количество раскачиваний и дополнительных оборотов не ограничивается.','Оценивается общее время четырех серий; время между сериями не останавливается.','Выполнять упражнение без крепления ремнями рук и ног к раме лопинга запрещено.'],equipment:['Лопинг','Фиксирующие ремни для рук и ног','Секундомер'],figure:94,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
65:{start:'Стоя в центре батута; спортивная форма одежды.',execution:['Исходное положение — стоя в центре батута. По команде «ВПЕРЕД» выполнить необходимое количество подготовительных прыжков до оптимальной высоты и удобного положения.','Военно-транспортная и дальняя авиация, вариант 1: прыжок вверх в группировке; прыжок вверх; прыжок вверх согнувшись; прыжок вверх; прыжок вверх ноги врозь; прыжок вверх; остановка.','Военно-транспортная и дальняя авиация, вариант 2: прыжок вверх в группировке; прыжок вверх согнувшись; прыжок вверх ноги врозь; прыжок вверх с поворотом на 360°; остановка.','Военно-транспортная и дальняя авиация, вариант 3: прыжок в сед; прыжок из седа вперед на ноги; прыжок вперед на живот; прыжок с живота назад на ноги; прыжок вверх с поворотом на 360°; остановка.','Армейская авиация, вариант 1: прыжок в сед; прыжок из седа вперед на ноги; прыжок вверх в группировке; прыжок вперед на живот; прыжок с живота назад на спину; прыжок со спины вперед на ноги; прыжок вверх; остановка.','Армейская авиация, вариант 2: прыжок назад на спину в группировке; прыжок со спины вперед на ноги; прыжок вверх в группировке; прыжок вперед на живот; прыжок с живота назад на ноги; прыжок вверх согнувшись; прыжок вверх с поворотом на 180°; прыжок вверх ноги врозь; прыжок в сед; прыжок из седа вперед на ноги; прыжок вверх; остановка.','Армейская авиация, вариант 3: прыжок в сед; прыжок из седа вперед с поворотом на 180° в сед; прыжок из седа вперед на ноги; прыжок вверх с поворотом на 180°; прыжок вперед на живот; прыжок с живота назад на спину; прыжок со спины вперед на ноги с поворотом на 180°; прыжок вверх; остановка.','Оперативно-тактическая авиация, вариант 1: прыжок на живот с поворотом на 180°; прыжок с живота назад на ноги; прыжок вверх с поворотом на 180°; прыжок назад на спину в группировке; прыжок со спины вперед на живот; прыжок с живота назад на ноги; прыжок на спину с поворотом на 180°; прыжок со спины вперед на ноги с поворотом на 180°; прыжок вверх; остановка.','Оперативно-тактическая авиация, вариант 2: сальто назад (вперед); прыжок вверх согнувшись; прыжок в сед; прыжок из седа вперед на живот; прыжок с живота назад на ноги; прыжок вверх ноги врозь; прыжок на спину с поворотом на 180°; прыжок со спины с поворотом на 180° на спину; прыжок со спины назад на ноги; прыжок вверх; остановка.','Оперативно-тактическая авиация, вариант 3: три четверти сальто вперед на спину; прыжок со спины вперед на ноги с поворотом на 180°; прыжок вверх ноги врозь; прыжок вперед на живот; прыжок с живота с поворотом на 180° по горизонтали на живот; прыжок с живота назад на ноги; прыжок вверх согнувшись; сальто назад в группировке; прыжок вверх в группировке; сальто вперед на ноги; прыжок вверх; остановка.'],rules:['Три варианта сложности предусмотрены для военно-транспортной и дальней авиации, армейской авиации и оперативно-тактической авиации; военнослужащий выбирает комбинацию своего рода авиации.','Упражнение не выполнено, если комбинация прервана или элементы выполнены не в соответствии с описанием и последовательностью.','При падении предоставляется вторая попытка.','Оценка: вариант 3 — 100 баллов, вариант 2 — 70 баллов, вариант 1 — 40 баллов.'],equipment:['Гимнастический батут','Безопасная зона и маты согласно требованиям оборудования'],figure:95,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
66:{start:'Стойка ноги врозь перед ящиком для боеприпасов.',execution:['По команде «К СНАРЯДУ» присесть и взять ящик за ручки.','Встать, подняв ящик на грудь.','Поднять ящик вверх и зафиксировать его на прямых руках.','Опустить ящик вниз и вернуться в исходное положение.','Продолжать повторения в течение трех минут.'],rules:['Масса ящика — 30 кг; допускается наполнение любым грузом.','Разрешается отдыхать в исходном положении.','Бросать ящик запрещено.','При нарушении условий повторение не засчитывается.','Выполняется в военной форме, бронежилете, защитном шлеме, с автоматом и пристегнутым магазином или массогабаритным макетом.'],equipment:['Ящик с ручками массой 30 кг','Военная форма одежды','Бронежилет и защитный шлем','Автомат с пристегнутым магазином или массогабаритный макет'],figure:96,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
67:{start:'Упор лежа на предплечьях: предплечья параллельны, пальцы сжаты в кулак, тело прямое, ноги вместе.',execution:['По команде «К выполнению упражнения — ПРИСТУПИТЬ» принять упор лежа на предплечьях.','Зафиксировать прямое положение тела и сохранять его неподвижно.','Время фиксируется с момента принятия правильного положения до нарушения условий.'],rules:['Разведение ног и касание пола коленями не допускаются.','При нарушении условий время останавливается, подается команда «СТОП».'],equipment:['Ровная нескользкая поверхность','Секундомер'],figure:97,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
68:{start:'На линии выполнения упражнения; военная форма и установленное защитное снаряжение.',execution:['Выполнить две зачетные попытки на дальность в установленном коридоре.','Результат фиксируется по дальности засчитанной попытки в пределах коридора.'],rules:['Используется массогабаритный макет ручной гранаты Ф-1 массой 600–620 г.','Ширина коридора — 10 м; боковые линии не входят в границы коридора.','Предоставляются две попытки.','Карточка содержит нормативные параметры и оценку, но не описывает технику метания; выполнение проводится по официальной инструкции и под контролем руководителя.'],equipment:['Размеченный коридор шириной 10 м','Массогабаритный макет ручной гранаты Ф-1 массой 600–620 г','Установленная форма и защитное снаряжение'],figure:98,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_4/uprazhnenie-n-68/'},
69:{start:'На линии выполнения упражнения; военная форма и установленное защитное снаряжение.',execution:['Выполнить один пробный и три зачетных броска по обозначенной цели.','Результат определяется количеством засчитанных попаданий в круг.'],rules:['Используется массогабаритный макет гранаты РГД-5 или РГН массой 310–330 г.','Диаметр круга — 4 м; расстояние от линии метания до центра круга — 25 м.','Центр круга обозначается белым флажком высотой 50 см.','Карточка содержит нормативные параметры и оценку, но не описывает технику метания; выполнение проводится по официальной инструкции и под контролем руководителя.'],equipment:['Размеченная площадка и круг диаметром 4 м','Массогабаритный макет гранаты РГД-5 или РГН','Установленная форма и защитное снаряжение'],figure:99,source:common,sourceUrl:'https://sudact.ru/law/prikaz-ministra-oborony-rf-ot-20042023-n_1/prilozhenie/prilozhenie-n-5/spetsialnye-fizicheskie-uprazhneniia/fizicheskie-uprazhneniia-napravlennye-na-formirovanie_4/uprazhnenie-n-69/'},
70:{start:'Неподвижный вис на перекладине хватом сверху, ноги вместе.',execution:['По команде принять неподвижное положение виса.','Удерживать положение без движения ног, рук и туловища как можно дольше.','Время фиксируется до первого нарушения неподвижного положения.'],rules:['Выполняется в военной форме одежды.','Движения ног, рук и тела не допускаются.'],equipment:['Гимнастическая перекладина','Секундомер'],figure:100,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'}
,20:{start:'Исходное положение на стартовой тумбе, рядом с ней либо в воде у бортика бассейна.',execution:['По команде «ЗАНЯТЬ МЕСТА» занять место для старта.','По команде «НА СТАРТ» принять неподвижное положение.','По звуковому сигналу или команде «МАРШ» преодолеть 50 м любым способом плавания.','На повороте и финише коснуться поворотного щита любой частью тела.'],rules:['Выполняется в спортивной форме одежды в плавательном бассейне или на оборудованной водной станции.','Разрешается любой способ плавания.','Не допускаются старт раньше команды, касание дна бассейна и захват за разграничительные дорожки.'],equipment:['Плавательный бассейн или оборудованная водная станция','Стартовая тумба или бортик','Поворотный щит и разграничительные дорожки'],figure:19,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
21:{start:'Исходное положение на стартовой тумбе, рядом с ней либо в воде у бортика бассейна.',execution:['По команде «ЗАНЯТЬ МЕСТА» занять место для старта.','По команде «НА СТАРТ» принять неподвижное положение.','По звуковому сигналу или команде «МАРШ» преодолеть 100 м любым способом плавания.','На повороте и финише коснуться поворотного щита любой частью тела.'],rules:['Выполняется в спортивной форме одежды в плавательном бассейне или на оборудованной водной станции.','Разрешается любой способ плавания.','Не допускаются старт раньше команды, касание дна бассейна и захват за разграничительные дорожки.'],equipment:['Плавательный бассейн или оборудованная водная станция','Стартовая тумба или бортик','Поворотный щит и разграничительные дорожки'],figure:19,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
22:{start:'Исходное положение на стартовой тумбе, рядом с ней либо в воде у бортика бассейна.',execution:['По команде «ЗАНЯТЬ МЕСТА» занять место для старта.','По команде «НА СТАРТ» принять неподвижное положение.','По звуковому сигналу или команде «МАРШ» преодолеть 100 м способом брасс.','На повороте и финише коснуться поворотного щита любой частью тела.'],rules:['Выполняется в спортивной форме одежды в бассейне или на оборудованной водной станции.','Дистанция преодолевается способом плавания брасс.','Не допускаются старт раньше команды, касание дна бассейна и захват за разграничительные дорожки.'],equipment:['Плавательный бассейн или оборудованная водная станция','Стартовая тумба или бортик','Поворотный щит и разграничительные дорожки'],figure:20,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
23:{start:'Высокий старт за стартовой линией; одна нога впереди, другая отставлена назад.',execution:['По команде «НА СТАРТ» занять исходное положение.','По команде «ВНИМАНИЕ» принять неподвижное положение старта.','По команде «МАРШ!» начать бег и преодолеть 400 м.'],rules:['Выполняется в спортивной форме одежды по беговой дорожке стадиона или ровной площадке с пригодным покрытием.','Не допускаются создание помех другому военнослужащему и фальстарт.'],equipment:['Беговая дорожка стадиона или ровная площадка с пригодным покрытием'],figure:21,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
24:{start:'Общий старт за стартовой линией.',execution:['По команде «НА СТАРТ» подойти к стартовой линии.','По команде «МАРШ» начать бег и преодолеть дистанцию 1 км.','Финишировать после полного преодоления дистанции.'],rules:['Выполняется в спортивной форме одежды на беговой дорожке стадиона или ровной дороге вне стадиона.','Старт и финиш, как правило, оборудуются в одном месте.','При выполнении на стадионе старт и финиш определяются разметкой стадиона.'],equipment:['Беговая дорожка стадиона или ровная дорога вне стадиона','Размеченные старт и финиш'],figure:22,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
25:{start:'Общий старт за стартовой линией.',execution:['По команде «НА СТАРТ» подойти к стартовой линии.','По команде «МАРШ» начать бег и преодолеть дистанцию 3 км.','Финишировать после полного преодоления дистанции.'],rules:['Выполняется в спортивной форме одежды на беговой дорожке стадиона или ровной дороге вне стадиона.','Старт и финиш, как правило, оборудуются в одном месте.','При выполнении на стадионе старт и финиш определяются разметкой стадиона.'],equipment:['Беговая дорожка стадиона или ровная дорога вне стадиона','Размеченные старт и финиш'],figure:22,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'},
26:{start:'Общий старт за стартовой линией.',execution:['По команде «НА СТАРТ» подойти к стартовой линии.','По команде «МАРШ» начать бег и преодолеть дистанцию 5 км.','Финишировать после полного преодоления дистанции.'],rules:['Выполняется в спортивной форме одежды на беговой дорожке стадиона или ровной дороге вне стадиона.','Старт и финиш, как правило, оборудуются в одном месте.','При выполнении на стадионе старт и финиш определяются разметкой стадиона.'],equipment:['Беговая дорожка стадиона или ровная дорога вне стадиона','Размеченные старт и финиш'],figure:22,source:common,sourceUrl:'https://normativfp.ru/wiki/docs/prikaz-230-nfp-red-08-12-2025.pdf'}


};